8	export default async function ConsolidatePage() {
9	  const user = await requireUser();
10	  const servers = await db.server.findMany({
11	    where: { userId: user.id },
12	    orderBy: { createdAt: "desc" },
13	    select: { id: true, hostname: true, label: true },
14	  });
15	  const serverOptions = servers.map((s) => ({ id: s.id, name: s.label || s.hostname }));
16	
17	  return (
18	    <div>
19	      <PortalHero
20	        variant="migrate"
21	        title="Consolidate servers"
22	        sub="Merge several source servers onto one Nxeon box. We scan each, flag collisions, and migrate them in sequence."
23	      />
24	      <ConsolidateWizard servers={serverOptions} />
25	    </div>
26	  );
27	}
