1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { encryptSecret } from "./crypto-box";
7	import { checkRateLimit } from "./rate-limit";
8	import { SANDBOX } from "./sandbox";
9	import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "./ssh-exec";
10	import { detectSource, syntheticScan, parseSizeLabel, type ScanResult } from "../worker/migrate-detect";
11	import { recommendPlanSizing, type SizingVerdict } from "./migrate-sizing";
12	import { cleanHostname, pointHostnameToIp } from "./cloudflare-point";
13	import { readStoredCloudflare } from "./cloudflare-oauth";
14	import { resolvePublicHost, BlockedHostError } from "./tools/net-guard";
15	import { planConsolidation, consolidationBlockers, inventoryFromScan, type ConsolidationPlan, type Collision } from "./migrate-consolidate";
16	
17	export type { ScanResult } from "../worker/migrate-detect";
18	export type { SizingVerdict } from "./migrate-sizing";
19	
20	/**
21	 * VPS migration — pull a customer's files + databases from another provider's
22	 * VPS onto their new Nxeon server. The customer supplies SSH credentials for the
23	 * SOURCE box; we only ever verify ownership of the TARGET (Nxeon) server.
24	 *
25	 * All source secrets (the SSH password and each database password) are encrypted
26	 * at rest with the shared AES-256-GCM box in lib/crypto-box.ts (`encryptSecret`),
27	 * the SAME helper used for mailbox/BYOK secrets. They are CLEARED by the worker
28	 * (worker/migrate.ts) the moment the migration finishes — success or failure —
29	 * so a completed Migration row never retains usable credentials. Nothing here
30	 * ever returns a decrypted secret (or the ciphertext) to the client.
31	 *
32	 * The heavy lifting runs in the `MIGRATE` worker job; this module only validates
33	 * input, encrypts secrets, records the Migration row and enqueues the job.
34	 */
35	
36	// ---- Input shapes (mirrors the Migration.items Json) ------------------------
37	
38	export type CreateMigrationInput = {
39	  serverId: string; // target Nxeon server (must be owned by the caller)
40	  sourceHost: string; // FQDN or IP of the source VPS
41	  sourcePort?: number; // SSH port, default 22
42	  sourceUser?: string; // SSH user, default "root" (we use root's LOCAL auth to dump DBs)
43	  sourcePassword: string; // SSH password for the source box
44	  paths?: string[]; // file paths to copy from the source (to the same paths on the target)
45	  /**
46	   * Read-only auto-detection snapshot (from scanSource). Carries NO secrets. We
47	   * derive the whole lift-and-shift plan (which DB engines to dump passwordlessly,
48	   * Docker volumes/compose dirs, prerequisites to install, ports to verify) from
49	   * it, and store both the plan and the snapshot under Migration.items — reusing
50	   * the existing Json column rather than adding a schema field (another agent
51	   * owns the schema this wave).
52	   */
53	  scan?: ScanResult;
54	  /**
55	   * Explicit opt-in to use an attached block-storage volume for Docker's stores
56	   * (`/var/lib/docker` + `/var/lib/containerd`). **Defaults to false.**
57	   *
58	   * Volumes are portable: the Volumes UI promises they can be attached to any of
59	   * the customer's running servers, and their data survives a server rebuild.
60	   * Mounting a system path on a volume silently ends that — the server can no
61	   * longer boot properly without it. So this is never inferred from free space;
62	   * the customer ticks a box in the wizard that says so in as many words. Stored
63	   * under Migration.items (an existing Json column) — no schema change.
64	   */
65	  useVolumeForDocker?: boolean;
66	  /**
67	   * Consolidation only: source-path → distinct-target-path map, so a colliding
68	   * path (two sources both at `/var/www/html`) is copied to its own directory
69	   * rather than overwriting the earlier source. Set by `startConsolidationMigration`
70	   * from the collision plan; absent (undefined) on every normal single-source run.
71	   */
72	  pathRemap?: Record<string, string>;
73	  /**
74	   * Per-migration SAFETY opt-ins from the wizard's "Advanced options". Each
75	   * defaults to OFF. Persisted onto `Migration.items.options` (an existing Json
76	   * column — no schema change) and read by the worker per run. When omitted the
77	   * worker falls back to the global env flags (the rehearsal harness sets those),
78	   * so existing callers behave exactly as before.
79	   *   overwriteTargetData — replace a same-named DB / non-fresh app path on the target.
80	   *   renameClones        — bring up a compose clone that shares hardcoded container_names by namespacing them.
81	   *   copySshKeys         — copy authorized_keys (public keys only — never private keys).
82	   */
83	  options?: { overwriteTargetData?: boolean; renameClones?: boolean; copySshKeys?: boolean };
84	};
85	
86	// The passwordless lift-and-shift plan, derived from the scan + selected paths and
87	// carried through Migration.items (secret-free). The worker re-validates every
88	// value against strict shell-inert allowlists before it is used in a command.
89	type MigrationPlan = {
90	  dbEngines: ("mysql" | "postgres")[];
91	  dockerVolumes: string[];
92	  composeDirs: string[];
93	  verifyPorts: number[];
94	  hasContainers: boolean;
95	  webServers: ("nginx" | "apache")[];
96	  runtimes: ("nodejs" | "python3")[];
97	};
98	
99	// ---- Client-safe row shapes (NEVER include secrets) -------------------------
100	
101	export type MigrationDatabaseView = {
102	  engine: string;
103	  name: string;
104	  user: string;
105	};
106	
107	export type MigrationRow = {
108	  id: string;
109	  serverId: string;
110	  serverName: string | null;
111	  sourceHost: string;
112	  sourcePort: number;
113	  sourceUser: string;
114	  paths: string[];
115	  databases: MigrationDatabaseView[];
116	  status: string;
117	  progress: number;
118	  step: string | null;
119	  log: string | null;
120	  lastError: string | null;
121	  createdAt: string;
122	  finishedAt: string | null;
123	};
124	
125	// ---- Validation -------------------------------------------------------------
126	
127	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
128	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
129	// resolution; this only rejects obvious junk before we store anything.
130	const HOST_RE =
131	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
132	const DEFAULT_PATHS = ["/var/www", "/home"];
133	const MAX_PATHS = 40;
134	
135	function cleanPaths(paths: string[] | undefined): string[] {
136	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
137	    .map((p) => p.trim())
138	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
139	  // De-dupe while preserving order.
140	  return [...new Set(list)].slice(0, MAX_PATHS);
141	}
142	
143	// Docker volume names are shell-inert (docker's own charset) — the worker
144	// re-validates, but we only ever store well-formed names.
145	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
146	function isCopyableAbsPath(p: string): boolean {
147	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
148	}
149	
150	/**
151	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
152	 * of paths the customer chose to copy. Databases are auto-included whenever an
153	 * engine was detected (no password needed — the worker dumps via root's local
154	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
155	 * can install them on the target. Everything here is secret-free.
156	 */
157	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
158	  const empty: MigrationPlan = {
159	    dbEngines: [],
160	    dockerVolumes: [],
161	    composeDirs: [],
162	    verifyPorts: [],
163	    hasContainers: false,
164	    webServers: [],
165	    runtimes: [],
166	  };
167	  if (!scan || !scan.ok) return empty;
168	  const pathSet = new Set(selectedPaths);
169	
170	  // Auto-include every detected engine (dump passwordlessly via root local auth).
171	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
172	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
173	  );
174	
175	  const containers = scan.containers ?? [];
176	  // Named Docker volumes = container mounts that are NOT absolute host paths.
177	  const dockerVolumes = [
178	    ...new Set(
179	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
180	    ),
181	  ].slice(0, 60);
182	
183	  // Compose project dirs among the app dirs the customer is actually copying.
184	  const composeDirs = [
185	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
186	  ].slice(0, 40);
187	
188	  // Ports we will hold the migration accountable for. ONLY the customer's own
189	  // services — never the base operating system's.
190	  //
191	  // This used to be every listening port on the source except 22, so a stock
192	  // Debian box handed the customer `25` (exim4, installed by the distro and never
193	  // configured), `5355` (systemd-resolved's mDNS stub) and `53` as "not up on the
194	  // target yet — start the owning app/service". Those are not the customer's
195	  // software, were never part of what they asked to move, and cannot be started
196	  // by them in any meaningful sense. Seven of twenty-two action items in the
197	  // 2026-07-26 rehearsal were this noise, which is how a real action item gets
198	  // lost: a list that cries wolf is a list nobody reads to the end of.
199	  //
200	  // Filtering by PORT NUMBER would be the wrong fix — a customer really can run
201	  // their own mail server on 25. The honest discriminator is the OWNING PROCESS,
202	  // which the scan already captured, so a port is dropped only when the thing
203	  // listening on it is a distro daemon we did not migrate.
204	  const OS_DAEMONS =
205	    /^(systemd-resolve|systemd-resolved|systemd-network|exim4?|sendmail|postfix|rpcbind|rpc\.statd|avahi-daemon|cupsd|chronyd?|ntpd|dhclient|dhcpcd|named|dnsmasq|snapd|multipathd|master)$/i;
206	  const verifyPorts = [
207	    ...new Set(
208	      (scan.ports ?? [])
209	        .filter((p) => {
210	          if (!Number.isInteger(p.port) || p.port < 1 || p.port > 65535 || p.port === 22) return false;
211	          // No owning process recorded: keep it. An unknown is reported, never
212	          // silently dropped — that is the mistake this whole engine exists to
213	          // stop making.
214	          const proc = (p.proc || "").trim().toLowerCase();
215	          if (!proc) return true;
216	          return !OS_DAEMONS.test(proc);
217	        })
218	        .map((p) => p.port)
219	    ),
220	  ].slice(0, 60);
221	
222	  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
223	
224	  // Web servers: match the owning process/service names, else default to nginx
225	  // when web roots exist (the overwhelmingly common case).
226	  const procBlob = [
227	    ...(scan.ports ?? []).map((p) => p.proc || ""),
228	    ...(scan.services ?? []).map((s) => s.name || ""),
229	  ]
230	    .join(" ")
231	    .toLowerCase();
232	  const webServers: ("nginx" | "apache")[] = [];
233	  if (/nginx/.test(procBlob)) webServers.push("nginx");
234	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
235	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
236	
237	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
238	  const runtimeBlob = [
239	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
240	    ...(scan.ports ?? []).map((p) => p.proc || ""),
241	  ]
242	    .join(" ")
243	    .toLowerCase();
244	  const runtimes: ("nodejs" | "python3")[] = [];
245	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
246	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
247	
248	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
249	}
250	
251	const GiB = 1024 ** 3;
252	
253	/** Working headroom the transfer needs while images load/unpack. Mirrors the
254	 *  engine's pre-flight allowance in worker/migrate-real.ts so the wizard's
255	 *  "will it fit?" answer and the worker's refusal can never disagree. */
256	const MIGRATION_HEADROOM_BYTES = 2 * GiB;
257	void MIGRATION_HEADROOM_BYTES; // kept for reference; the worker owns the headroom allowance
258	
259	/**
260	 * Sum (in bytes) of the SELECTED migration items, plus the DB data-dir estimate
261	 * when a database engine was detected (databases are auto-included). Sizes come
262	 * from the read-only scan's human size labels; unknown-size items (custom folders,
263	 * Docker mounts) count as 0. Used both for the client storage panel and the
264	 * worker pre-flight — computed server-side here so the stored total is trusted.
265	 */
266	function selectedMigrationBytes(scan: ScanResult | undefined, selectedPaths: string[]): number {
267	  if (!scan || !scan.ok) return 0;
268	  const sizeByPath = new Map<string, number>();
269	  for (const w of scan.webRoots ?? []) sizeByPath.set(w.path, parseSizeLabel(w.sizeLabel));
270	  for (const h of scan.homes ?? []) sizeByPath.set(h.path, parseSizeLabel(h.sizeLabel));
271	  for (const a of scan.appDirs ?? []) sizeByPath.set(a.path, parseSizeLabel(a.sizeLabel));
272	  let total = 0;
273	  for (const p of selectedPaths) total += sizeByPath.get(p) ?? 0;
274	  // Databases are auto-included whenever an engine is present.
275	  const enginePresent = (scan.engines ?? []).some((e) => e.present);
276	  if (enginePresent) total += Math.max(0, scan.dbSizeBytes ?? 0);
277	  // CONTRACT — this is FILES ONLY (selected paths + the DB data-dir estimate).
278	  // It is stored as `items.totalBytes`, and the worker pre-flight reads it as
279	  // `fileBytes` and then adds the Docker image allowance + headroom ITSELF
280	  // (worker/migrate-real.ts). Adding Docker here as well made the engine count it
281	  // TWICE — a ~12 GB move was reported as needing 83.6 GB and refused. The wizard
282	  // displays the combined figure by computing its own file/Docker split
283	  // client-side; it never renders this value, so keep this files-only.
284	  return Math.round(total);
285	}
