287	/** Parse ID / VERSION_ID / PRETTY_NAME lines from `/etc/os-release` (never sourced). */
288	function parseOsRelease(stdout: string): { id: string; versionId: string; pretty: string } | null {
289	  const o: Record<string, string> = {};
290	  for (const line of (stdout ?? "").split("\n")) {
291	    const m = /^(ID|VERSION_ID|PRETTY_NAME)=(.*)$/.exec(line.trim());
292	    if (!m) continue;
293	    o[m[1]] = m[2].trim().replace(/^["']|["']$/g, "").slice(0, 128);
294	  }
295	  if (!o.ID && !o.PRETTY_NAME && !o.VERSION_ID) return null;
296	  return {
297	    id: (o.ID ?? "").toLowerCase().slice(0, 32),
298	    versionId: (o.VERSION_ID ?? "").slice(0, 32),
299	    pretty: o.PRETTY_NAME ?? "",
300	  };
301	}
302	
303	/**
304	 * Validate a customer-named SOURCE host and resolve it to a vetted PUBLIC
305	 * address.
306	 *
307	 * This module's whole job is to SSH, from inside the platform, into a machine
308	 * whose address, username and password the customer types into a form. `HOST_RE`
309	 * checked only that the string looked like a host — so `10.20.0.137`,
310	 * `127.0.0.1` and the Proxmox host's own address all passed. That made the
311	 * migration wizard three things it was never meant to be:
312	 *
313	 *   - an internal PORT SCANNER of 10.20.0.0/24, which is every other customer's
314	 *     VPS, distinguishable because `scanSource` reports "couldn't sign in"
315	 *     (something is listening and speaking SSH) separately from "couldn't reach"
316	 *     (nothing there);
317	 *   - an SSH CREDENTIAL-STUFFING engine against those same machines, since the
318	 *     password is supplied per attempt;
319	 *   - a way to point it at the hypervisor and the platform's own loopback.
320	 *
321	 * A real migration source is always a public IP at another provider, so refusing
322	 * private / loopback / link-local / reserved targets costs a legitimate customer
323	 * nothing. `resolvePublicHost` (lib/tools/net-guard.ts) also resolves the name
324	 * itself and rejects if ANY A/AAAA record is private, which closes the DNS
325	 * rebinding variant — a name that answers public on our check and private on the
326	 * connect. The vetted address is returned so the caller can connect to the IP we
327	 * actually checked rather than re-resolving.
328	 */
329	/* The documentation ranges the wizard's own placeholder suggests — RFC 5737
330	   for addresses, RFC 2606 for names. They are reserved, so the real vetting
331	   rejects them, which left the sandbox unable to get past step 2 while telling
332	   the tester to type "203.0.113.10 or old.example.com".
333	
334	   Allowed ONLY under NXEON_SANDBOX, where `scanSource` returns a synthetic
335	   detection before any socket is opened and no worker exists to act on the
336	   result — so nothing is ever connected to. In every other environment these
337	   stay blocked with everything else: the vetting below is what stops this
338	   wizard being an internal port scanner and SSH credential-stuffer pointed at
339	   other customers' VMs, and it is not relaxed there for any reason. */
340	const DOC_HOST_RE = /^(?:192\.0\.2\.\d{1,3}|198\.51\.100\.\d{1,3}|203\.0\.113\.\d{1,3}|(?:[a-z0-9-]+\.)*example\.(?:com|net|org)|(?:[a-z0-9-]+\.)*(?:test|invalid|localhost\.example))$/i;
341	
342	async function vettedSourceHost(
343	  raw: string | undefined,
344	): Promise<{ host: string; address: string } | { error: string }> {
345	  const host = (raw ?? "").trim();
346	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
347	    return { error: "Enter a valid source host — an IP address or domain name." };
348	  }
349	  if (SANDBOX && DOC_HOST_RE.test(host)) {
350	    return { host, address: host };
351	  }
352	  try {
353	    const resolved = await resolvePublicHost(host);
354	    return { host, address: resolved.addresses[0] ?? host };
355	  } catch (e) {
356	    if (e instanceof BlockedHostError) {
357	      return {
358	        error:
359	          `We can't migrate from ${host}: ${e.message} ` +
360	          `The source has to be a server reachable on the public internet — use its public IP address ` +
361	          `or a domain name that points at it, not a private/LAN address.`,
362	      };
363	    }
364	    return {
365	      error:
366	        `We couldn't look up ${host}. Check the spelling, or enter the source server's public IP address instead.`,
367	    };
368	  }
369	}
370	
371	async function ownedTargetServer(serverId: string) {
372	  const user = await requireUser();
373	  const server = await db.server.findUnique({ where: { id: serverId } });
374	  if (!server) throw new Error("Not found");
375	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
376	  return { user, server };
377	}
378	
379	// ---- Consolidation planning (N sources → one target) ------------------------
380	
381	export type ConsolidationSourceInput = {
382	  label: string; // short stable label, e.g. "srv-a"
383	  host: string;
384	  scan: ScanResult; // from scanSource
385	  domains?: string[]; // domains this source serves (from the scan/vhosts)
386	};
387	
388	/**
389	 * READ-ONLY pre-flight for consolidating several source servers onto one target.
390	 * Builds each source's resource inventory from its scan, runs the pure collision
391	 * planner (lib/migrate-consolidate.ts) and returns the auto-remap plan for the
392	 * operator to approve. No writes, no SSH, no engine work — just the plan. The
393	 * actual sequential migrations (which carry each remap in Migration.items) and
394	 * the engine-side application of the remap are the execution half, kept separate
395	 * so this preview can never mutate anything.
396	 */
397	export async function planConsolidationMigration(input: {
398	  serverId: string;
399	  sources: ConsolidationSourceInput[];
400	}): Promise<{ error?: string; plan?: ConsolidationPlan }> {
401	  const { user, server } = await ownedTargetServer(input.serverId);
402	  void server;
403	  if (!Array.isArray(input.sources) || input.sources.length < 2) {
404	    return { error: "Add at least two source servers to consolidate." };
405	  }
406	  if (input.sources.length > 10) {
407	    return { error: "You can consolidate up to 10 servers at a time." };
408	  }
409	  const rl = checkRateLimit(`migrate:consolidate-plan:${user.id}`, { max: 20, windowMs: 10 * 60 * 1000 });
410	  if (!rl.ok) return { error: `Slow down — try again in ${rl.retryAfterSec}s.` };
411	
412	  const inventories = input.sources.map((s) =>
413	    inventoryFromScan(String(s.label || s.host).slice(0, 40), String(s.host).slice(0, 253), {
414	      scan: {
415	        ports: s.scan.ports ?? [],
416	        appDirs: [
417	          ...(s.scan.appDirs ?? []).map((d) => ({ path: d.path })),
418	          ...(s.scan.webRoots ?? []).map((w) => ({ path: w.path })),
419	          ...(s.scan.homes ?? []).map((h) => ({ path: h.path })),
420	        ],
421	        containers: (s.scan.containers ?? []).map((c) => ({ mounts: c.mounts })),
422	      },
423	      items: { databases: (s.scan.databases ?? []).map((d) => ({ name: d.name })) },
424	      domains: s.domains ?? [],
425	    }),
426	  );
427	
428	  // Fresh targets have nothing yet; when consolidating onto a box that already
429	  // runs apps, its inventory would seed the "used" sets here (future: scan target).
430	  const plan = planConsolidation(inventories, {});
431	  return { plan };
432	}
433	
434	export type ConsolidationStartSource = Omit<CreateMigrationInput, "serverId"> & { label?: string; domains?: string[] };
435	
436	function inventoriesForSources(sources: ConsolidationStartSource[]) {
437	  return sources.map((s, i) =>
438	    inventoryFromScan(String(s.label || s.sourceHost || `src-${i + 1}`).slice(0, 40), String(s.sourceHost).slice(0, 253), {
439	      scan: {
440	        ports: s.scan?.ports ?? [],
441	        appDirs: [
442	          ...(s.scan?.appDirs ?? []).map((d) => ({ path: d.path })),
443	          ...(s.scan?.webRoots ?? []).map((w) => ({ path: w.path })),
444	          ...(s.scan?.homes ?? []).map((h) => ({ path: h.path })),
445	        ],
446	        containers: (s.scan?.containers ?? []).map((c) => ({ mounts: c.mounts })),
447	      },
448	      items: { databases: (s.scan?.databases ?? []).map((d) => ({ name: d.name })) },
449	      domains: s.domains ?? [],
450	    }),
451	  );
452	}
453	
454	/**
455	 * Consolidate several source servers onto ONE target. Builds the collision plan
456	 * and REFUSES (returning the blockers) when sources overlap on ports or paths —
457	 * those need the verified engine remap step before they can auto-run without risk
458	 * of one app clobbering another. When there are no such blockers, it creates a
459	 * migration per source; the serial worker imports them one after another onto the
460	 * same target. Domain overlaps are allowed (you point DNS where you choose).
461	 */
462	export async function startConsolidationMigration(input: {
463	  serverId: string;
464	  sources: ConsolidationStartSource[];
465	}): Promise<{ error?: string; ids?: string[]; blockers?: Collision[]; plan?: ConsolidationPlan }> {
466	  const { user } = await ownedTargetServer(input.serverId);
467	  if (!Array.isArray(input.sources) || input.sources.length < 2) {
468	    return { error: "Add at least two source servers to consolidate." };
469	  }
470	  if (input.sources.length > 5) {
471	    return { error: "You can consolidate up to 5 servers at a time." };
472	  }
473	  const rl = checkRateLimit(`migrate:consolidate:${user.id}`, { max: 3, windowMs: 30 * 60 * 1000 });
474	  if (!rl.ok) return { error: `Slow down — try again in ${rl.retryAfterSec}s.` };
475	
476	  const plan = planConsolidation(inventoriesForSources(input.sources), {});
477	  const blockers = consolidationBlockers(plan);
478	  const portBlk = blockers.filter((b) => b.kind === "port");
479	  const pathBlk = blockers.filter((b) => b.kind === "path");
480	  const ex = (arr: Collision[]) => [...new Set(arr.map((b) => b.value))].slice(0, 3).join(", ");
481	
482	  // Port overlaps can never auto-resolve: two apps cannot share a port, and the
483	  // app's own bind config is not ours to guess. Always block.
484	  if (portBlk.length) {
485	    return { error: `These servers overlap on ports (${ex(portBlk)}). Two apps can't share a port — change one at the source, then consolidate.`, blockers, plan };
486	  }
487	  // Path overlaps: the engine copies each colliding path to its OWN directory (no
488	  // data loss), then reports where it landed so you point the app's config there.
489	  // Gated behind NXEON_CONSOLIDATE_REMAP until validated on a migration rehearsal.
490	  const remapEnabled = !!process.env.NXEON_CONSOLIDATE_REMAP && process.env.NXEON_CONSOLIDATE_REMAP !== "0";
491	  if (pathBlk.length && !remapEnabled) {
492	    return { error: `These servers overlap on paths (${ex(pathBlk)}). Path auto-remap is behind NXEON_CONSOLIDATE_REMAP until it's validated on a rehearsal — enable it, migrate the overlapping ones one at a time, or change them at the source.`, blockers, plan };
493	  }
494	
495	  // Hand each source to the normal migration path (the serial worker sequences the
496	  // jobs so imports don't race), carrying that source's path remap in items.
497	  const labels = input.sources.map((s, i) => String(s.label || s.sourceHost || `src-${i + 1}`).slice(0, 40));
498	  const ids: string[] = [];
499	  for (let i = 0; i < input.sources.length; i++) {
500	    const s = input.sources[i];
501	    const pathRemap: Record<string, string> = {};
502	    for (const rm of plan.remaps) if (rm.sourceLabel === labels[i] && rm.path) pathRemap[rm.path.from] = rm.path.to;
503	    const res = await createMigration({ ...s, serverId: input.serverId, pathRemap: Object.keys(pathRemap).length ? pathRemap : undefined });
504	    if (res.error) return { error: `Source ${s.sourceHost}: ${res.error}`, ids, plan };
505	    if (res.id) ids.push(res.id);
506	  }
507	  return { ids, plan };
508	}
