510	function toRow(
511	  m: {
512	    id: string;
513	    serverId: string;
514	    sourceHost: string;
515	    sourcePort: number;
516	    sourceUser: string;
517	    items: unknown;
518	    status: string;
519	    progress: number;
520	    step: string | null;
521	    log: string | null;
522	    lastError: string | null;
523	    createdAt: Date;
524	    finishedAt: Date | null;
525	  },
526	  server: { hostname: string; label: string | null } | null
527	): MigrationRow {
528	  const items = (m.items ?? {}) as {
529	    paths?: string[];
530	    databases?: { engine?: string; name?: string; user?: string }[];
531	    dbEngines?: string[];
532	  };
533	  // Databases are now auto-included per detected engine (no per-DB list). For the
534	  // client view, surface one row per engine; fall back to any legacy per-DB list.
535	  const dbView: MigrationDatabaseView[] =
536	    Array.isArray(items.databases) && items.databases.length
537	      ? items.databases.map((d) => ({
538	          engine: String(d.engine ?? ""),
539	          name: String(d.name ?? ""),
540	          user: String(d.user ?? ""),
541	        }))
542	      : Array.isArray(items.dbEngines)
543	        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
544	        : [];
545	  return {
546	    id: m.id,
547	    serverId: m.serverId,
548	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
549	    // caller resolves the server row and passes it in.
550	    serverName: server ? server.label || server.hostname : null,
551	    sourceHost: m.sourceHost,
552	    sourcePort: m.sourcePort,
553	    sourceUser: m.sourceUser,
554	    paths: Array.isArray(items.paths) ? items.paths : [],
555	    // Never expose any DB secret — dbView carries only non-sensitive fields.
556	    databases: dbView,
557	    status: m.status,
558	    progress: m.progress,
559	    step: m.step,
560	    log: m.log,
561	    lastError: m.lastError,
562	    createdAt: m.createdAt.toISOString(),
563	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
564	  };
565	}
