569	/**
570	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
571	 * ownership, validates the source connection details, encrypts every source
572	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
573	 * the new migration id; never returns any secret.
574	 */
575	export async function createMigration(
576	  input: CreateMigrationInput
577	): Promise<{ error?: string; id?: string }> {
578	  const { user, server } = await ownedTargetServer(input.serverId);
579	
580	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
581	  // credential-stuffing the wizard against arbitrary source hosts.
582	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
583	  if (!rl.ok) {
584	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
585	  }
586	
587	  // Same public-address gate as scanSource — the worker will SSH here.
588	  const vetted = await vettedSourceHost(input.sourceHost);
589	  if ("error" in vetted) return { error: vetted.error };
590	  const host = vetted.host;
591	
592	  const port = input.sourcePort ?? 22;
593	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
594	    return { error: "SSH port must be between 1 and 65535." };
595	  }
596	
597	  const sourceUser = (input.sourceUser ?? "root").trim();
598	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
599	    return { error: "Enter the SSH username on the source server." };
600	  }
601	
602	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
603	    return { error: "Enter the SSH password for the source server." };
604	  }
605	
606	  const paths = cleanPaths(input.paths);
607	
608	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
609	  // Databases are auto-included when an engine is detected — no DB password is
610	  // ever collected; the worker dumps via root's local socket/peer auth.
611	  const plan = derivePlan(input.scan, paths);
612	
613	  // Persist the (secret-free) detection snapshot alongside the plan so the
614	  // migration is traceable back to what auto-detection found. Reusing items
615	  // avoids a schema change (Migration.items is a Json column).
616	  const scanSnapshot =
617	    input.scan && input.scan.ok
618	      ? {
619	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
620	          homes: input.scan.homes?.slice(0, 40) ?? [],
621	          databases: input.scan.databases?.slice(0, 60) ?? [],
622	          engines: input.scan.engines ?? [],
623	          // Exact engine variant + version — lets the worker install the MATCHING
624	          // engine on the target for a clean same-engine restore.
625	          dbEngines: input.scan.dbEngines ?? [],
626	          // Running-app discovery — informational, secret-free, for traceability.
627	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
628	          containers: input.scan.containers?.slice(0, 30) ?? [],
629	          ports: input.scan.ports?.slice(0, 60) ?? [],
630	          services: input.scan.services?.slice(0, 30) ?? [],
631	          // Storage-guardrail + compatibility inputs (secret-free, for traceability
632	          // and the worker pre-flight).
633	          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
634	          sourceOs: input.scan.sourceOs ?? null,
635	          sourceArch: input.scan.sourceArch ?? null,
636	          synthetic: !!input.scan.synthetic,
637	        }
638	      : undefined;
639	
640	  // Trusted server-side total of what will be migrated (bytes) — carried through
641	  // items so the worker's pre-flight guard can compare it to target free disk
642	  // without re-scanning. No schema change: Migration.items is a Json column.
643	  const totalBytes = selectedMigrationBytes(input.scan, paths);
644	
645	  const items = {
646	    paths,
647	    dbEngines: plan.dbEngines,
648	    dockerVolumes: plan.dockerVolumes,
649	    composeDirs: plan.composeDirs,
650	    verifyPorts: plan.verifyPorts,
651	    hasContainers: plan.hasContainers,
652	    webServers: plan.webServers,
653	    runtimes: plan.runtimes,
654	    totalBytes,
655	    // Explicit consent only — coerced to a real boolean so nothing else can ride
656	    // in on this field, and only ever true when the customer ticked the box.
657	    useVolumeForDocker: input.useVolumeForDocker === true,
658	    // Consolidation only: source→target path remap so a colliding path lands in
659	    // its own dir instead of overwriting an earlier source. Absent on normal runs.
660	    ...(input.pathRemap && Object.keys(input.pathRemap).length ? { remap: { paths: input.pathRemap } } : {}),
661	    // Per-migration SAFETY opt-ins. Only written when the caller supplies them, so
662	    // an omitted `options` leaves items.options undefined and the worker uses the
663	    // env-flag fallback (behaves exactly as before). Each field is coerced to a
664	    // strict boolean and defaults OFF so nothing else can ride in and no safety
665	    // default is weakened.
666	    ...(input.options
667	      ? {
668	          options: {
669	            overwriteTargetData: input.options.overwriteTargetData === true,
670	            renameClones: input.options.renameClones === true,
671	            copySshKeys: input.options.copySshKeys === true,
672	          },
673	        }
674	      : {}),
675	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
676	  };
677	
678	  const migration = await db.migration.create({
679	    data: {
680	      userId: user.id,
681	      serverId: server.id,
682	      sourceHost: host,
683	      sourcePort: port,
684	      sourceUser,
685	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
686	      items,
687	      status: "PENDING",
688	      progress: 0,
689	      step: "Queued",
690	    },
691	  });
692	
693	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
694	  // traceability); the handler loads everything else from payload.migrationId.
695	  await db.job.create({
696	    data: {
697	      type: "MIGRATE",
698	      serverId: server.id,
699	      payload: { migrationId: migration.id },
700	    },
701	  });
702	
703	  await db.auditLog.create({
704	    data: {
705	      userId: user.id,
706	      action: "migration.create",
707	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
708	    },
709	  });
710	
711	  revalidatePath("/dashboard/migrate");
712	  return { id: migration.id };
713	}
