715	/**
716	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
717	 * caller owns the TARGET server (authz + a stricter rate limit than create),
718	 * validates the source connection details, then SSHes into the source and
719	 * inventories web roots / home directories / databases — never writing anything
720	 * on the source and never persisting the supplied credentials.
721	 *
722	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
723	 * are NOT stored anywhere; the client re-supplies them to createMigration once
724	 * the customer confirms what to move. Returns a secret-free ScanResult.
725	 *
726	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
727	 * a real SSH connection, so staging stays fully self-contained.
728	 */
729	export async function scanSource(input: {
730	  serverId: string;
731	  sourceHost: string;
732	  sourcePort?: number;
733	  sourceUser?: string;
734	  sourcePassword: string;
735	  dbUser?: string;
736	  dbPassword?: string;
737	}): Promise<{ error?: string; scan?: ScanResult; sizing?: SizingVerdict }> {
738	  const { user, server } = await ownedTargetServer(input.serverId);
739	  const targetPlan = server.planId
740	    ? await db.plan.findUnique({ where: { id: server.planId }, select: { ramMB: true } })
741	    : null;
742	  const sizingFor = (scan: ScanResult): SizingVerdict =>
743	    recommendPlanSizing({
744	      sourceMemMB: scan.sourceMemMB,
745	      sourceMemUsedMB: scan.sourceMemUsedMB,
746	      containerCount: scan.containers?.length,
747	      targetRamMB: targetPlan?.ramMB ?? 0,
748	    });
749	
750	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
751	  // than migration creation to stop the wizard being used to probe hosts.
752	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
753	  if (!rl.ok) {
754	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
755	  }
756	
757	  // Refuse private / loopback / reserved targets BEFORE anything is logged or
758	  // connected to. See vettedSourceHost: without this the wizard is an internal
759	  // port scanner and SSH credential-stuffer aimed at every other customer's VM.
760	  const vetted = await vettedSourceHost(input.sourceHost);
761	  if ("error" in vetted) return { error: vetted.error };
762	  const host = vetted.host;
763	  const port = input.sourcePort ?? 22;
764	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
765	    return { error: "SSH port must be between 1 and 65535." };
766	  }
767	  const sourceUser = (input.sourceUser ?? "root").trim();
768	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
769	    return { error: "Enter the SSH username on the source server." };
770	  }
771	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
772	    return { error: "Enter the SSH password for the source server." };
773	  }
774	
775	  await db.auditLog.create({
776	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
777	  }).catch(() => {});
778	
779	  // SANDBOX: never touch the outside world — hand back synthetic detection.
780	  if (SANDBOX) {
781	    const scan = syntheticScan({ dbPassword: input.dbPassword });
782	    return { scan, sizing: sizingFor(scan) };
783	  }
784	
785	  // Hard overall timeout so a slow/hostile source can't hang the request.
786	  const HARD_TIMEOUT_MS = 90_000;
787	  try {
788	    const scan = await Promise.race<ScanResult>([
789	      detectSource({
790	        // The ADDRESS we vetted, not the name — a name can resolve public for
791	        // our check and private for the connect (DNS rebinding).
792	        host: vetted.address,
793	        port,
794	        user: sourceUser,
795	        password: input.sourcePassword,
796	        dbUser: input.dbUser?.trim() || undefined,
797	        dbPassword: input.dbPassword || undefined,
798	      }),
799	      new Promise<ScanResult>((_, reject) =>
800	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
801	      ),
802	    ]);
803	    return { scan, sizing: sizingFor(scan) };
804	  } catch (e: any) {
805	    const msg = `${e?.message ?? e}`;
806	    // Map the common connection failures to friendly, non-leaky copy.
807	    if (/authentication|denied|password/i.test(msg)) {
808	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
809	    }
810	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
811	      return { error: "Couldn't reach the source server — check the host and SSH port." };
812	    }
813	    return { error: "We couldn't scan that server. Double-check the details and try again." };
814	  }
815	}
