817	// ---- Target free-space + OS probe (storage & compatibility guardrails) ------
818	
819	export type TargetInfo = {
820	  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
821	  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
822	  os: { id: string; versionId: string; pretty: string } | null;
823	  arch: string | null;
824	  /**
825	   * Capacity of the LARGEST attached-but-unformatted block device (a volume the
826	   * customer added but hasn't used yet), or null if there isn't one.
827	   *
828	   * This is capacity that is available **only if the customer chooses to use it**
829	   * — the engine can format it and relocate the container stores onto it, but it
830	   * never does so on its own (see `useVolumeForDocker`). Volumes are portable
831	   * add-on storage, and mounting a system path on one makes it undetachable, so
832	   * the wizard presents this as an opt-in, not as free space.
833	   *
834	   * The LARGEST, not the sum: separate volumes are separate filesystems and the
835	   * engine uses exactly one. They are deliberately never combined into an LVM
836	   * pool — that would weld them together and destroy the portability of all of
837	   * them at once.
838	   */
839	  spareDiskBytes?: number | null;
840	  /**
841	   * How many unused volumes are attached. 2+ means the panel should say that only
842	   * the largest can be used, so the customer isn't left expecting them to add up.
843	   */
844	  spareDiskCount?: number | null;
845	};
846	
847	/**
848	 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
849	 * space and OS/architecture, so the wizard can show the storage headroom and the
850	 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
851	 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
852	 *
853	 * Failure is graceful: if the server is unreachable or df can't be parsed we
854	 * return `disk: null` (the UI shows "couldn't read free space" and allows the
855	 * migration with a soft warning rather than a hard block). OS falls back to the
856	 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
857	 */
858	export async function targetDiskFree(
859	  serverId: string
860	): Promise<{ error?: string; info?: TargetInfo }> {
861	  const { server } = await ownedTargetServer(serverId);
862	
863	  // OS fallback from the known OS template (works even if the box is unreachable).
864	  const tmpl = await db.osTemplate
865	    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
866	    .catch(() => null);
867	  const osFallback = tmpl
868	    ? {
869	        id: (tmpl.family || "linux").toLowerCase(),
870	        versionId: tmpl.version || "",
871	        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
872	      }
873	    : null;
874	
875	  if (SANDBOX) {
876	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
877	    return {
878	      info: {
879	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
880	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
881	        arch: "x86_64",
882	      },
883	    };
884	  }
885	
886	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
887	  const full = await db.server.findUnique({
888	    where: { id: server.id },
889	    include: { dedicatedIp: true },
890	  });
891	
892	  try {
893	    const info = await withServerSsh(full as any, async (conn) => {
894	      // Root filesystem size/used/avail in bytes.
895	      const dfr = await exec(
896	        conn,
897	        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
898	        QUICK_TIMEOUT_MS
899	      );
900	      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
901	      let disk: TargetInfo["disk"] = null;
902	      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
903	        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
904	      }
905	      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
906	      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
907	      const osr = await exec(
908	        conn,
909	        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
910	        QUICK_TIMEOUT_MS
911	      ).catch(() => ({ stdout: "" }) as any);
912	      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
913	      // Attached-but-unformatted disks (unused volumes the customer added).
914	      // Read-only probe, and it mirrors the engine's qualification bar exactly so
915	      // the panel can never promise space the engine would refuse to touch: a
916	      // disk counts only when nothing in its tree has a filesystem or mount, it
917	      // has no children, nothing holds it, `blkid` finds no signature at all,
918	      // and it is at least the engine's 4 GiB floor.
919	      let spareDiskBytes: number | null = null;
920	      let spareDiskCount: number | null = null;
921	      try {
922	        const lb = await exec(
923	          conn,
924	          "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
925	            "[ -n \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ] && continue; " +
926	            "[ -n \"$(lsblk -no NAME /dev/$d 2>/dev/null | tail -n +2)\" ] && continue; " +
927	            "[ -n \"$(ls -A /sys/block/$d/holders 2>/dev/null)\" ] && continue; " +
928	            "blkid /dev/$d >/dev/null 2>&1 && continue; " +
929	            "sz=$(lsblk -bdn -o SIZE /dev/$d 2>/dev/null | tr -d ' '); " +
930	            "[ -z \"$sz\" ] && continue; " +
931	            "[ \"$sz\" -ge 4294967296 ] 2>/dev/null && echo \"$sz\"; done",
932	          QUICK_TIMEOUT_MS
933	        );
934	        const sizes = ((lb.stdout as string) || "")
935	          .split("\n")
936	          .map((s) => Number(s.trim()))
937	          .filter((n) => Number.isFinite(n) && n > 0);
938	        if (sizes.length) {
939	          // The LARGEST, never the sum — the engine uses exactly one volume and
940	          // does not combine them, so summing would promise space that no single
941	          // filesystem will ever have. The count lets the panel say so plainly.
942	          spareDiskCount = sizes.length;
