1050	/**
1051	 * Candidate domains to point at the migration's target server, cheapest source
1052	 * first. Ownership-checked (the migration must be the caller's).
1053	 *
1054	 *   1. `Domain` rows — domains the customer registered with us.
1055	 *   2. Websites already configured on the target server.
1056	 *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
1057	 *      — web-root folders are conventionally named after the vhost. The snapshot
1058	 *      does not record nginx/apache `server_name` values, so this is a best-effort
1059	 *      read of what was already captured; we never re-scan the source.
1060	 */
1061	export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
1062	  const user = await requireUser();
1063	
1064	  const m = await db.migration.findUnique({ where: { id: migrationId } });
1065	  if (!m) return { error: "Migration not found." };
1066	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };
1067	
1068	  const server = await db.server.findUnique({
1069	    where: { id: m.serverId },
1070	    select: {
1071	      hostname: true,
1072	      label: true,
1073	      ipAddress: true,
1074	      dedicatedIp: { select: { address: true } },
1075	      node: { select: { publicIp: true } },
1076	    },
1077	  });
1078	
1079	  const seen = new Set<string>();
1080	  const candidates: DnsCandidate[] = [];
1081	  const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
1082	    const host = cleanHostname(raw ?? "");
1083	    if (!host || seen.has(host)) return;
1084	    seen.add(host);
1085	    candidates.push({ host, source });
1086	  };
1087	
1088	  const domains = await db.domain.findMany({
1089	    where: { userId: m.userId },
1090	    select: { name: true },
1091	    orderBy: { name: "asc" },
1092	    take: 50,
1093	  });
1094	  for (const d of domains) push(d.name, "registered");
1095	
1096	  const sites = await db.website.findMany({
1097	    where: { serverId: m.serverId },
1098	    select: { domain: true },
1099	    take: 50,
1100	  });
1101	  for (const s of sites) push(s.domain, "website");
1102	
1103	  // Only what the scan already stored — no new source-scanning here.
1104	  const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
1105	  for (const w of items.scan?.webRoots ?? []) {
1106	    if (w?.path) push(hostnameFromPath(w.path), "scan");
1107	  }
1108	
1109	  return {
1110	    // ipAddress is the server's PRIVATE address (10.20.x.x) — never a valid DNS
1111	    // target; fall back to the server's own node's public IP first.
1112	    targetIp: server?.dedicatedIp?.address ?? server?.node?.publicIp ?? server?.ipAddress ?? null,
1113	    targetName: server ? server.label || server.hostname : null,
1114	    candidates: candidates.slice(0, 40),
1115	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
1116	  };
1117	}
