1175	// ---- Post-migration remediation (Layer 2) ----------------------------------
1176	// A migration finishes COMPLETED_WITH_ISSUES when a source domain does not serve
1177	// on the new server yet — usually because an app did not auto-start. Rather than
1178	// leaving the customer to SSH in, the PLATFORM (which holds root SSH to the
1179	// target) finishes it on their behalf, over its own connection, from a button.
1180	//
1181	// These are TARGET-side only: the source password is cleared once a migration
1182	// ends, so re-pulling from the source is out of scope here (that needs a
1183	// reconnect flow). What they DO cover is the common case — bring up copied
1184	// compose stacks, start the units the engine created, reload nginx, and re-probe
1185	// each domain HONESTLY (a placeholder page is not "serving", per the #59 gate).
1186	
1187	const REMEDIATE_COMPOSE_FILES =
1188	  "docker-compose.yml docker-compose.yaml compose.yml compose.yaml docker-compose.prod.yml docker-compose.prod.yaml docker-compose.production.yml compose.prod.yml compose.production.yml docker-compose.override.yml compose.override.yml";
1189	// The distribution placeholder pages that must never count as a live site.
1190	const PLACEHOLDER_RE =
1191	  /Apache2 Debian Default Page|Welcome to nginx|Test Page for the .* HTTP Server|Your IP address is/i;
1192	const REMEDIATE_PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
1193	
1194	export type SiteServingView = { domain: string; serving: boolean; code: string };
1195	export type RemediationResult = {
1196	  error?: string;
1197	  ok?: boolean;
1198	  /** Domains that serve their real site now. */
1199	  serving?: string[];
1200	  /** Domains that still do not serve. */
1201	  dark?: string[];
1202	  /** Did the whole migration flip to fully-served (status → DONE)? */
1203	  allServing?: boolean;
1204	  /** Short human lines describing what the finish step did. */
1205	  log?: string[];
1206	};
