1208	async function ownedMigrationForRemediation(id: string) {
1209	  const user = await requireUser();
1210	  const m = await db.migration.findUnique({ where: { id } });
1211	  if (!m) return { error: "That migration no longer exists." as const };
1212	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." as const };
1213	  const server = await db.server.findUnique({
1214	    where: { id: m.serverId },
1215	    select: {
1216	      id: true,
1217	      hostname: true,
1218	      rootPassword: true,
1219	      rootPasswordEnc: true,
1220	      sshPort: true,
1221	      dedicatedIp: { select: { address: true } },
1222	    },
1223	  });
