1228	/** The domains to re-check: what the source served, from the stored scan. */
1229	function migrationProbeDomains(items: unknown): string[] {
1230	  const scan = ((items ?? {}) as { scan?: { vhostDomains?: unknown[] } }).scan ?? {};
1231	  const out = new Set<string>();
1232	  for (const d of scan.vhostDomains ?? []) {
1233	    const h = cleanHostname(String(d ?? ""));
1234	    if (h) out.add(h);
1235	  }
1236	  return [...out].slice(0, 30);
1237	}
