1239	/**
1240	 * Ask the TARGET (over its own loopback, so no DNS is needed) what it serves for
1241	 * `domain`, and whether that is a real site or a placeholder. HTTPS is checked
1242	 * first (authoritative when a cert exists), then HTTP.
1243	 */
1244	async function probeDomainOnTarget(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domain: string): Promise<SiteServingView> {
1245	  if (!/^[a-z0-9.-]{1,253}$/.test(domain)) return { domain, serving: false, code: "000" };
1246	  const httpsCode = (
1247	    await exec(conn, `curl -sk -o /tmp/nxeon-probe -m 8 --resolve ${domain}:443:127.0.0.1 -w '%{http_code}' https://${domain}/ 2>/dev/null`, 15000)
1248	  ).stdout.trim().slice(0, 3);
1249	  let code = httpsCode;
1250	  if (!/^[1-9]\d\d$/.test(code)) {
1251	    code = (
1252	      await exec(conn, `curl -s -o /tmp/nxeon-probe -m 8 -H 'Host: ${domain}' -w '%{http_code}' http://127.0.0.1/ 2>/dev/null`, 15000)
1253	    ).stdout.trim().slice(0, 3);
1254	  }
1255	  const body = (await exec(conn, `head -c 4096 /tmp/nxeon-probe 2>/dev/null`, 10000)).stdout;
1256	  const serving = /^(2|3)\d\d$/.test(code) && !PLACEHOLDER_RE.test(body);
1257	  return { domain, serving, code: code || "000" };
1258	}
