1260	async function reprobeAndSettle(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domains: string[]): Promise<SiteServingView[]> {
1261	  const results = new Map<string, SiteServingView>();
1262	  for (const d of domains) results.set(d, await probeDomainOnTarget(conn, d));
1263	  return [...results.values()];
1264	}
