1266	async function persistServingOutcome(migrationId: string, currentStatus: string, probes: SiteServingView[]): Promise<boolean> {
1267	  const dark = probes.filter((p) => !p.serving);
1268	  const allServing = probes.length > 0 && dark.length === 0;
1269	  // Only ever UPGRADE the honest verdict — a re-check that finds everything live
1270	  // flips COMPLETED_WITH_ISSUES → DONE. Never downgrade (that belongs to the
1271	  // engine's own run, not a spot re-check).
1272	  if (allServing && currentStatus === "COMPLETED_WITH_ISSUES") {
1273	    await db.migration.update({
1274	      where: { id: migrationId },
1275	      data: { status: "DONE", step: "Completed — all sites serving" },
1276	    }).catch(() => {});
1277	  }
1278	  return allServing;
1279	}
