1281	/**
1282	 * Re-check (only) whether each site serves now, and flip the migration to DONE
1283	 * if they all do. No bring-up — just an honest re-probe. Cheap; safe to spam.
1284	 */
1285	export async function recheckMigrationServing(migrationId: string): Promise<RemediationResult> {
1286	  const ctx = await ownedMigrationForRemediation(migrationId);
1287	  if ("error" in ctx) return { error: ctx.error };
1288	  const { m, server, user } = ctx;
1289	  const rl = checkRateLimit(`migrate:recheck:${user.id}`, { max: 20, windowMs: 5 * 60 * 1000 });
1290	  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before checking again.` };
1291	  const domains = migrationProbeDomains(m.items);
1292	  if (!domains.length) return { ok: true, serving: [], dark: [], allServing: false, log: ["No domains to check."] };
1293	  if (SANDBOX) {
1294	    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended all sites serve."] };
1295	  }
1296	  try {
1297	    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
1298	    const allServing = await persistServingOutcome(m.id, m.status, probes);
1299	    revalidatePath("/dashboard/migrate");
1300	    return {
1301	      ok: true,
1302	      serving: probes.filter((p) => p.serving).map((p) => p.domain),
1303	      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
1304	      allServing,
1305	    };
1306	  } catch {
1307	    return { error: "Couldn't reach the new server to check. Try again in a moment." };
1308	  }
1309	}
