1311	/**
1312	 * Finish the migration the customer couldn't: bring up any copied compose stacks,
1313	 * start the units the engine created (incl. the reproduced pm2/manual-start
1314	 * apps), reload nginx, then re-probe. Everything here is idempotent and
1315	 * TARGET-side; it never touches the old server and never removes anything.
1316	 */
1317	export async function finishMigrationSetup(migrationId: string): Promise<RemediationResult> {
1318	  const ctx = await ownedMigrationForRemediation(migrationId);
1319	  if ("error" in ctx) return { error: ctx.error };
1320	  const { m, server, user } = ctx;
1321	  const rl = checkRateLimit(`migrate:finish:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
1322	  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before trying again.` };
1323	  const domains = migrationProbeDomains(m.items);
1324	  const composeDirs = (((m.items ?? {}) as { composeDirs?: unknown[] }).composeDirs ?? [])
1325	    .map((p) => String(p ?? ""))
1326	    .filter((p) => REMEDIATE_PATH_RE.test(p))
1327	    .slice(0, 20);
1328	  if (SANDBOX) {
1329	    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended to finish setup."] };
1330	  }
1331	  const log: string[] = [];
1332	  try {
1333	    await withServerSsh(server, async (conn) => {
1334	      // 1. Bring up copied compose stacks (idempotent; -f for non-default names).
1335	      for (const dir of composeDirs) {
1336	        const cf = (
1337	          await exec(conn, `for f in ${REMEDIATE_COMPOSE_FILES}; do [ -f ${dir}/$f ] && { echo ${dir}/$f; break; }; done`, 15000)
1338	        ).stdout.trim();
1339	        if (!REMEDIATE_PATH_RE.test(cf)) continue;
1340	        const fArg = /\/(docker-compose|compose)\.ya?ml$/.test(cf) ? "" : `-f ${cf} `;
1341	        const r = await exec(conn, `sh -c 'cd ${dir} && docker compose ${fArg}up -d' 2>&1 | tail -2`, 300000);
1342	        log.push(`Started ${dir.split("/").pop()}: ${r.stdout.trim().slice(0, 100) || "ok"}`);
1343	      }
1344	      // 2. Start the units the engine created that aren't running yet.
1345	      await exec(
1346	        conn,
1347	        `for u in $(systemctl list-unit-files 'nxeon-app-*.service' --no-legend 2>/dev/null | awk '{print $1}'); do systemctl start "$u" 2>/dev/null || true; done`,
1348	        60000
1349	      );
1350	      // 3. Reload nginx if its config is valid.
1351	      await exec(conn, `nginx -t >/dev/null 2>&1 && systemctl reload nginx 2>/dev/null || true`, 30000);
1352	      log.push("Reloaded the web server.");
1353	    });
1354	    // 4. Give the just-started apps a moment, then probe honestly.
1355	    await new Promise((r) => setTimeout(r, 12000));
1356	    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
1357	    const allServing = await persistServingOutcome(m.id, m.status, probes);
1358	    revalidatePath("/dashboard/migrate");
1359	    return {
1360	      ok: true,
1361	      serving: probes.filter((p) => p.serving).map((p) => p.domain),
1362	      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
1363	      allServing,
1364	      log,
1365	    };
1366	  } catch {
1367	    return { error: "Couldn't finish setup on the new server. Your old server is still serving — try again shortly." };
1368	  }
1369	}
